from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
HTML = ROOT / 'dashboard' / 'static' / 'index.html'
text = HTML.read_text(encoding='utf-8')
if 'id="incidentCommandCenter"' in text:
    print('Milestone 7.2 already applied.')
    raise SystemExit(0)
css_anchor = '  .empty { color: var(--muted-dim); font-style: italic; font-size: 13px; padding: 12px 0; }\n'
css = '''  .incident-command { margin-bottom:16px; }\n  .incident-toolbar { display:flex; justify-content:space-between; align-items:center; gap:12px; margin-bottom:12px; flex-wrap:wrap; }\n  .incident-filters { display:flex; gap:6px; flex-wrap:wrap; }\n  .incident-filter { padding:6px 10px; border:1px solid var(--border); background:var(--card); color:var(--muted); border-radius:7px; cursor:pointer; font-size:11px; font-weight:800; }\n  .incident-filter.active { color:var(--text); border-color:var(--red); background:var(--red-dim); }\n  .incident-row { display:grid; grid-template-columns:90px minmax(0,1fr) 110px 92px; gap:12px; align-items:center; padding:12px 0; border-bottom:1px solid var(--border); }\n  .incident-row:last-child { border-bottom:none; }\n  .incident-severity { font-size:10px; font-weight:900; letter-spacing:.5px; }\n  .incident-title { font-size:13px; font-weight:800; }\n  .incident-meta { color:var(--muted); font-size:11px; margin-top:3px; }\n  .incident-action { font-size:11px; font-weight:800; padding:6px 9px; border:1px solid var(--border); background:var(--card); color:var(--text); border-radius:6px; cursor:pointer; }\n  .rca-drawer { display:none; margin-top:12px; border:1px solid var(--border); border-radius:10px; background:var(--card-hover); padding:16px; }\n  .rca-drawer.open { display:block; }\n  .rca-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; }\n  .rca-block { border:1px solid var(--border); border-radius:8px; padding:12px; }\n  .rca-label { color:var(--muted); font-size:10px; font-weight:900; letter-spacing:.8px; margin-bottom:6px; }\n  .rca-value { font-size:12.5px; line-height:1.55; }\n  .rca-list { margin:0; padding-left:18px; font-size:12px; line-height:1.6; }\n  @media (max-width: 760px) { .incident-row { grid-template-columns:1fr; gap:6px; } .rca-grid { grid-template-columns:1fr; } }\n'''
if css_anchor not in text: raise RuntimeError('7.2 CSS insertion point not found')
text = text.replace(css_anchor, css_anchor + css, 1)
html_anchor = '      <div class="two-col" style="margin-bottom:16px;">\n        <div class="list-card">\n'
html = '''      <div class="list-card incident-command" id="incidentCommandCenter">\n        <div class="incident-toolbar">\n          <div>\n            <div class="section-title" style="font-size:13px;">Incident command center</div>\n            <div class="section-sub">Authoritative incidents with evidence-focused AI RCA</div>\n          </div>\n          <div class="incident-filters">\n            <button class="incident-filter active" data-filter="ALL" onclick="setIncidentFilter('ALL')">All</button>\n            <button class="incident-filter" data-filter="CRITICAL" onclick="setIncidentFilter('CRITICAL')">Critical</button>\n            <button class="incident-filter" data-filter="WARNING" onclick="setIncidentFilter('WARNING')">Warning</button>\n            <button class="incident-filter" data-filter="RESOLVED" onclick="setIncidentFilter('RESOLVED')">Resolved</button>\n          </div>\n        </div>\n        <div id="incidentList"><div class="empty">No incidents.</div></div>\n        <div class="rca-drawer" id="rcaDrawer">\n          <div class="section-title" style="font-size:13px; margin-bottom:10px;" id="rcaTitle">Incident RCA</div>\n          <div id="rcaContent"><div class="empty">Select an incident.</div></div>\n        </div>\n      </div>\n\n'''
if html_anchor not in text: raise RuntimeError('7.2 HTML insertion point not found')
text = text.replace(html_anchor, html + html_anchor, 1)
js_anchor = 'let ackedAlerts = new Set();\n'
js = '''\nlet incidentFilter = "ALL";\n\nfunction setIncidentFilter(filter) {\n  incidentFilter = filter;\n  document.querySelectorAll(".incident-filter").forEach(b => b.classList.toggle("active", b.dataset.filter === filter));\n  renderIncidentCenter();\n}\n\nfunction incidentStatus(incident) { return String(incident.status || "").toUpperCase(); }\n\nfunction renderIncidentCenter() {\n  const list = document.getElementById("incidentList");\n  const incidents = [];\n  Object.keys(systemStatuses).forEach(system => {\n    const data = systemStatuses[system];\n    if (!data || !data.available) return;\n    (data.incidents || []).forEach(incident => incidents.push({system, incident}));\n  });\n  const filtered = incidents.filter(({incident}) => {\n    const sev = String(incident.severity || "UNKNOWN").toUpperCase();\n    const status = incidentStatus(incident);\n    if (incidentFilter === "RESOLVED") return status === "RESOLVED" || incident.resolved === true;\n    if (incidentFilter === "CRITICAL") return sev === "CRITICAL" && status !== "RESOLVED";\n    if (incidentFilter === "WARNING") return sev === "WARNING" && status !== "RESOLVED";\n    return true;\n  });\n  if (!filtered.length) { list.innerHTML = '<div class="empty">No incidents match this filter.</div>'; return; }\n  list.innerHTML = "";\n  filtered.slice(0, 12).forEach(({system, incident}) => {\n    const sev = String(incident.severity || "UNKNOWN").toUpperCase();\n    const color = statusColors[sev] || statusColors.UNKNOWN;\n    const row = document.createElement("div"); row.className = "incident-row";\n    row.innerHTML = `<div class="incident-severity" style="color:${color};">${sev}</div><div><div class="incident-title">${incident.title || incident.rule_id || "Incident"}</div><div class="incident-meta">${system} · ${incident.incident_id || "unknown"} · ${incident.status || "ACTIVE"}</div></div><div class="incident-meta">${timeAgo(incident.last_seen || incident.updated_at)}</div><button class="incident-action">View RCA</button>`;\n    row.querySelector(".incident-action").onclick = () => loadIncidentRca(incident.incident_id);\n    list.appendChild(row);\n  });\n}\n\nasync function loadIncidentRca(incidentId) {\n  const drawer = document.getElementById("rcaDrawer"); const content = document.getElementById("rcaContent");\n  drawer.classList.add("open"); document.getElementById("rcaTitle").textContent = "Incident RCA · " + incidentId;\n  content.innerHTML = '<div class="empty">Loading incident evidence...</div>';\n  if (!incidentId) { content.innerHTML = '<div class="empty">This incident has no persistent identity for RCA lookup.</div>'; return; }\n  try {\n    const res = await fetch("/api/incidents/" + encodeURIComponent(incidentId) + "/rca");\n    if (!res.ok) throw new Error("RCA request failed: " + res.status);\n    const payload = await res.json(); const incident = payload.incident || {}; const ai = payload.ai_analysis; const intel = payload.operational_intelligence;\n    const evidence = Array.isArray(incident.evidence) ? incident.evidence : [];\n    const actions = ai && Array.isArray(ai.recommended_actions) ? ai.recommended_actions : [];\n    const limitations = ai && Array.isArray(ai.limitations) ? ai.limitations : [];\n    content.innerHTML = `<div class="rca-grid"><div class="rca-block"><div class="rca-label">AUTHORITATIVE SEVERITY</div><div class="rca-value"><strong>${incident.severity || "UNKNOWN"}</strong> · ${incident.status || "UNKNOWN"}</div></div><div class="rca-block"><div class="rca-label">AI HYPOTHESIS</div><div class="rca-value">${ai ? (ai.likely_root_cause || ai.root_cause || "No hypothesis available.") : "No AI analysis available."}</div></div><div class="rca-block"><div class="rca-label">SUPPORTING EVIDENCE</div><ul class="rca-list">${(evidence.length ? evidence : ["No incident evidence recorded."]).map(x => `<li>${x}</li>`).join("")}</ul></div><div class="rca-block"><div class="rca-label">RECOMMENDED INVESTIGATION</div><ul class="rca-list">${(actions.length ? actions : ["Review the incident evidence and relevant SAP transaction logs."]).map(x => `<li>${x}</li>`).join("")}</ul></div></div>${intel ? `<div class="rca-block" style="margin-top:12px;"><div class="rca-label">OPERATIONAL INTELLIGENCE</div><div class="rca-value">${intel.overall_signal || "NO_SIGNIFICANT_INTELLIGENCE"} · score ${Number(intel.score || 0).toFixed(2)}</div></div>` : ""}${limitations.length ? `<div class="rca-block" style="margin-top:12px;"><div class="rca-label">LIMITATIONS</div><ul class="rca-list">${limitations.map(x => `<li>${x}</li>`).join("")}</ul></div>` : ""}`;\n  } catch (err) { content.innerHTML = '<div class="empty">RCA is unavailable for this incident. The incident itself remains authoritative.</div>'; }\n}\n'''
if js_anchor not in text: raise RuntimeError('7.2 JS insertion point not found')
text = text.replace(js_anchor, js_anchor + js, 1)
old = '  renderAlerts();\n  await loadActivity();'
new = '  renderAlerts();\n  renderIncidentCenter();\n  await loadActivity();'
if old not in text: raise RuntimeError('7.2 render hook not found')
text = text.replace(old, new, 1)
HTML.write_text(text, encoding='utf-8')
print('Milestone 7.2 applied safely.')
